custom_css:
/* 落樱 · SillyTavern 1.14.0 原生布局约束 */

#chat .mes:not([is_system="true"]) {
    max-width: 1040px;
    margin-inline: auto;
}

/* 保持官方 .mes 的 Flex，只交换角色消息两个直接子项。 */
#chat .mes[is_user="false"] > .mes_block {
    order: 1;
    flex: 1 1 0;
    width: auto;
    min-width: 0;
    margin-right: 12px;
}

#chat .mes[is_user="false"] > .mesAvatarWrapper {
    order: 2;
    flex: 0 0 var(--oy-avatar-size);
    margin-left: 14px;
}

#chat .mes[is_user="true"] > .mes_block {
    flex: 1 1 0;
    width: auto;
    min-width: 0;
}

#chat .mes[is_user="true"] > .mesAvatarWrapper {
    flex: 0 0 var(--oy-avatar-size);
    margin-right: 14px;
}

#chat :is(.mes_text, .mes_reasoning) :is(img, video, table, pre) {
    max-width: 100%;
}

#chat :is(.mes_text, .mes_reasoning) :is(pre, .table-container) {
    overflow-x: auto;
}
/* Theme author: @jiuyi0204 */

/* 落樱 · 全局视觉令牌与远程资源 */

@font-face {
    font-family: "Noto Sans SC OY";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4eff68933698e82715fcc4450c74b039c9988f19/font-library/v1/fonts/notosanssc/notosanssc.woff2") format("woff2");
    font-style: normal;
    font-weight: 100 900;
    font-display: swap;
}

@font-face {
    font-family: "LXGW WenKai OY";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/lxgwwenkai/lxgwwenkai.woff2") format("woff2");
    font-style: normal;
    font-weight: 400;
    font-display: swap;
}

:root {
    --oy-white: #ffffff;
    --oy-blush: #f7e8e8;
    --oy-mint: #cce2da;
    --oy-teal: #8ec9b7;
    --oy-coral: #df8d8e;
    --oy-crimson: #bc535d;
    --oy-ink: #3f3a3b;
    --oy-muted: #75696b;
    --oy-pale-ink: #8d7f81;
    --oy-line: rgba(188, 83, 93, 0.34);
    --oy-line-soft: rgba(142, 201, 183, 0.34);
    --oy-shadow: 0 12px 30px rgba(123, 73, 78, 0.12);
    --oy-shadow-soft: 0 4px 14px rgba(123, 73, 78, 0.10);
    --oy-radius-xs: 2px;
    --oy-radius-sm: 4px;
    --oy-radius-md: 6px;
    --oy-font-serif: "LXGW WenKai OY", "Kaiti SC", KaiTi, "Noto Serif CJK SC", serif;
    --oy-font-ui: "Noto Sans SC OY", "Noto Sans CJK SC", "Microsoft YaHei UI", system-ui, sans-serif;
    --oy-font-mono: "Cascadia Mono", "JetBrains Mono", Consolas, monospace;
    --mainFontFamily: var(--oy-font-serif);
    --oy-editorial-bg: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/f407698138db65cf691a578a7721b38db5725b0a/assets/%E8%90%BD%E6%A8%B1/background-editorial.webp");
    --oy-paper-texture: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/f407698138db65cf691a578a7721b38db5725b0a/assets/%E8%90%BD%E6%A8%B1/paper-texture.webp");
}

body {
    color: var(--oy-ink);
    background-color: var(--oy-white);
    background-image: var(--oy-editorial-bg);
    background-position: center;
    background-size: cover;
    font-family: var(--oy-font-serif);
    text-shadow: none;
}

#bg1,
#bg_custom {
    background-color: var(--oy-white);
    background-image: var(--oy-editorial-bg);
    background-position: center;
    background-size: cover;
}

@media (min-width: 701px) {
    /* 酒馆会以内联样式更新 #bg1；桌面主题背景需精确压过该单一属性。 */
    #bg1 {
        background-image: var(--oy-editorial-bg) !important;
        background-position: center;
        background-size: cover;
    }
}

/* 只隐藏浏览器滚动条外观；保留各容器原有 overflow 与全部滚动输入。 */
* {
    scrollbar-width: none !important;
    -ms-overflow-style: none !important;
}

::-webkit-scrollbar {
    display: none !important;
}

:is(#chat, #top-bar, #send_form, .drawer-content, .popup, .options-content, .menu, #options, #extensionsMenu) :focus-visible {
    outline: 2px solid var(--oy-crimson);
    outline-offset: 2px;
}

::selection {
    color: var(--oy-ink);
    background: rgba(204, 226, 218, 0.84);
}

/* W01 · 主聊天编辑长页母版 */

#sheld {
    border-inline: 1px solid var(--oy-line-soft);
    background-color: rgba(255, 255, 255, 0.40);
}

#chat {
    --oy-avatar-size: 64px;
    color: var(--oy-ink);
    background-color: var(--oy-white);
    background-image:
        linear-gradient(90deg, rgba(247, 232, 232, 0.24), transparent 12%, transparent 88%, rgba(204, 226, 218, 0.25)),
        linear-gradient(rgba(255, 255, 255, 0.54), rgba(255, 255, 255, 0.66)),
        var(--oy-editorial-bg),
        var(--oy-paper-texture);
    background-repeat: no-repeat, no-repeat, no-repeat, repeat;
    background-position: center, center, center, top left;
    background-size: 100% 100%, cover, cover, 420px 420px;
    background-blend-mode: normal, normal, multiply, normal;
    text-shadow: none;
}

#chat .mes:not([is_system="true"]) {
    position: relative;
    margin-block: 16px;
    padding: 22px 28px 18px;
    border: 1px solid var(--oy-line-soft);
    border-radius: var(--oy-radius-xs);
    color: var(--oy-ink);
    background-color: rgba(255, 255, 255, 0.82);
    background-image: linear-gradient(90deg, var(--oy-mint) 0 7px, transparent 7px);
    background-repeat: no-repeat;
    background-size: 100% 100%;
    box-shadow: var(--oy-shadow-soft);
    text-shadow: none;
}

#chat .mes[is_user="true"] {
    border-color: rgba(223, 141, 142, 0.42);
    background-color: rgba(247, 232, 232, 0.86);
    background-image: linear-gradient(90deg, var(--oy-coral) 0 7px, transparent 7px);
}

#chat .mes[is_user="false"]::before,
#chat .mes[is_user="true"]::before {
    position: absolute;
    top: 22px;
    z-index: 1;
    color: var(--oy-crimson);
    font: 600 10px/1 var(--oy-font-ui);
    letter-spacing: 0.18em;
    writing-mode: vertical-rl;
    pointer-events: none;
}

#chat .mes[is_user="false"]::before {
    content: "CHARACTER";
    left: 11px;
}

#chat .mes[is_user="true"]::before {
    content: "USER";
    right: 11px;
}

#chat .mes:not([is_system="true"])::after {
    content: "0" attr(mesid);
    position: absolute;
    right: 20px;
    bottom: 8px;
    color: rgba(188, 83, 93, 0.20);
    font: 800 30px/1 var(--oy-font-ui);
    letter-spacing: -0.06em;
    pointer-events: none;
}

#chat .mes[is_user="true"]::after {
    right: auto;
    left: 20px;
    color: rgba(142, 201, 183, 0.42);
}

#chat .mes:not([is_system="true"]) > .mesAvatarWrapper {
    position: relative;
    overflow: visible;
}

#chat .mes:not([is_system="true"]) .avatar,
#chat .mes:not([is_system="true"]) .avatar img {
    width: var(--oy-avatar-size);
    height: var(--oy-avatar-size);
    border-radius: 50%;
}

#chat .mes:not([is_system="true"]) .avatar {
    position: relative;
    flex: 0 0 var(--oy-avatar-size);
    overflow: hidden;
    border: 1px solid var(--oy-crimson);
    background-color: var(--oy-white);
    box-shadow: 0 0 0 4px var(--oy-white), 0 0 0 5px var(--oy-teal);
}

#chat .mes[is_user="true"] .avatar {
    border-color: var(--oy-teal);
    box-shadow: 0 0 0 4px var(--oy-blush), 0 0 0 5px var(--oy-coral);
}

#chat .mes:not([is_system="true"]) .avatar img {
    object-fit: cover;
    object-position: center;
}

#chat .mes:not([is_system="true"]) > .mes_block {
    color: var(--oy-ink);
    overflow-wrap: anywhere;
}

#chat .mes[is_user="false"] > .mes_block {
    padding: 0 18px 12px 26px;
    border-left: 1px solid var(--oy-line-soft);
}

#chat .mes[is_user="true"] > .mes_block {
    padding: 0 30px 12px 18px;
    border-right: 1px solid rgba(223, 141, 142, 0.34);
}

#chat .ch_name,
#chat .name_text {
    color: var(--oy-crimson);
    font-family: var(--oy-font-ui);
    font-weight: 700;
    letter-spacing: 0.05em;
}

#chat .mes[is_user="false"] .ch_name {
    padding-bottom: 7px;
    border-bottom: 1px solid var(--oy-line-soft);
}

#chat .timestamp,
#chat .mesIDDisplay,
#chat .mes_timer,
#chat .tokenCounterDisplay {
    color: var(--oy-muted);
    font-family: var(--oy-font-ui);
    font-size: 10px;
    text-shadow: none;
}

#chat :is(.mes_text, .mes_reasoning) {
    color: var(--oy-ink);
    font-family: var(--oy-font-serif);
    font-size: clamp(15px, 1vw, 17px);
    font-weight: 400;
    line-height: 1.9;
    letter-spacing: 0.025em;
    text-shadow: none;
}

#chat .mes[is_user="true"] :is(.mes_text, .mes_reasoning) {
    padding: 8px 16px;
    color: var(--oy-ink);
    border-left: 3px solid var(--oy-coral);
    background-color: rgba(255, 255, 255, 0.50);
    line-height: 1.72;
}

#chat .mes[is_user="false"] :is(.mes_text, .mes_reasoning) {
    min-height: 0;
    height: auto;
    padding: 10px clamp(24px, 3.6vw, 54px) 12px;
    background-color: transparent;
}

@media (min-width: 701px) {
    /* 右侧头像是独立 Flex 项；左侧建立等量正向留白后，内容区才与整张纸页同轴。 */
    #chat .mes[is_user="false"] > .mes_block {
        margin-left: calc(var(--oy-avatar-size) + 26px);
    }

    /* 段落仍左对齐；正文只在已经对称的内容区内使用正常居中外边距。 */
    #chat .mes[is_user="false"] .mes_text {
        box-sizing: border-box;
        inline-size: min(100%, 50rem);
        margin-inline: auto;
    }
}

#chat .mes_reasoning_header {
    color: var(--oy-crimson);
    border: 1px solid var(--oy-line-soft);
    border-radius: var(--oy-radius-sm);
    background-color: rgba(204, 226, 218, 0.72);
    box-shadow: none;
    text-shadow: none;
}

#chat .mes_reasoning_header:hover,
#chat .mes_reasoning_details[open] .mes_reasoning_header {
    color: var(--oy-white);
    border-color: var(--oy-crimson);
    background-color: var(--oy-crimson);
}

#chat .mes_reasoning_arrow {
    color: currentColor;
    opacity: 1;
    filter: none;
}

#chat :is(.mes_text, .mes_reasoning) blockquote {
    margin: 0.9em 0;
    padding: 10px 16px;
    color: var(--oy-ink);
    border-left: 3px solid var(--oy-teal);
    background-color: rgba(204, 226, 218, 0.44);
}

#chat :is(.mes_text, .mes_reasoning) hr {
    height: 1px;
    margin-block: 1.5em;
    border: 0;
    background: linear-gradient(90deg, transparent, var(--oy-crimson) 18% 38%, var(--oy-teal) 38% 82%, transparent);
}

#chat :is(.mes_text, .mes_reasoning) pre {
    color: var(--oy-ink);
    border: 1px solid var(--oy-line-soft);
    border-radius: var(--oy-radius-sm);
    background-color: rgba(255, 255, 255, 0.82);
    box-shadow: inset 4px 0 0 var(--oy-teal);
}

#chat :is(.mes_text, .mes_reasoning) :is(pre, code) {
    font-family: var(--oy-font-mono);
}

#chat :is(.mes_button, .extraMesButtons > div, .mes_edit_buttons .menu_button, .mes_reasoning_actions .edit_button) {
    color: var(--oy-crimson);
    opacity: 0.88;
    filter: none;
    text-shadow: none;
}

#chat :is(.mes_button, .extraMesButtons > div, .mes_edit_buttons .menu_button, .mes_reasoning_actions .edit_button):hover {
    color: var(--oy-crimson);
    opacity: 1;
    filter: none;
}

#chat .mes_edit_buttons .menu_button {
    color: var(--oy-crimson);
    border: 1px solid var(--oy-line);
    background-color: var(--oy-white);
    box-shadow: none;
}

#chat .mes_edit_done.menu_button {
    color: var(--oy-white);
    border-color: var(--oy-teal);
    background-color: var(--oy-teal);
}

#chat .mes_edit_cancel.menu_button {
    color: var(--oy-white);
    border-color: var(--oy-crimson);
    background-color: var(--oy-crimson);
}

#chat :is(.reasoning_edit_textarea, .edit_textarea) {
    color: var(--oy-ink);
    border: 1px solid var(--oy-line);
    background-color: rgba(255, 255, 255, 0.98);
    box-shadow: inset 4px 0 0 var(--oy-teal);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

#chat .mes[is_system="true"] {
    margin: 10px auto;
    border: 1px dashed var(--oy-line);
    border-radius: var(--oy-radius-sm);
    color: var(--oy-muted);
    background-color: rgba(255, 255, 255, 0.88);
    background-image: var(--oy-paper-texture);
    background-size: 420px 420px;
}

/* W02 · 顶栏九键：无重复独立底板 */

#top-bar {
    color: var(--oy-crimson);
    border-bottom: 1px solid var(--oy-line);
    border-radius: 0 0 var(--oy-radius-md) var(--oy-radius-md);
    background-color: rgba(255, 255, 255, 0.96);
    background-image:
        linear-gradient(90deg, var(--oy-crimson) 0 21%, var(--oy-coral) 21% 43%, var(--oy-blush) 43% 61%, var(--oy-mint) 61% 82%, var(--oy-teal) 82% 100%),
        var(--oy-paper-texture);
    background-position: top, center;
    background-repeat: no-repeat, repeat;
    background-size: 100% 4px, 420px 420px;
    box-shadow: var(--oy-shadow-soft);
    text-shadow: none;
}

#top-settings-holder :is(.drawer-icon, .drawer-toggle, .interactable) {
    color: var(--oy-teal);
    border: 0;
    border-radius: 0;
    background-color: transparent;
    box-shadow: inset 0 -2px 0 transparent;
    text-shadow: none;
}

#top-settings-holder :is(.drawer-icon, .drawer-toggle, .interactable):hover {
    color: var(--oy-crimson);
    background-color: rgba(247, 232, 232, 0.62);
    box-shadow: inset 0 -2px 0 var(--oy-coral);
    filter: none;
}

#top-settings-holder .openIcon,
#top-settings-holder :is(.drawer-icon, .drawer-toggle, .interactable)[aria-expanded="true"] {
    color: var(--oy-crimson);
    background-color: rgba(204, 226, 218, 0.54);
    box-shadow: inset 0 -3px 0 var(--oy-crimson);
    filter: none;
}

#ai-config-button,
#sys-settings-button,
#advanced-formatting-button,
#WI-SP-button,
#user-settings-button,
#backgrounds-button,
#extensions-settings-button,
#persona-management-button,
#rightNavHolder {
    background-color: transparent;
}

/* W03 · 输入页脚、菜单、魔法棒、发送/停止 */

#send_form {
    position: relative;
    color: var(--oy-ink);
    border: 1px solid var(--oy-line);
    border-radius: var(--oy-radius-sm);
    background-color: rgba(255, 255, 255, 0.97);
    background-image: var(--oy-paper-texture);
    background-repeat: repeat;
    background-size: 520px 520px;
    box-shadow: inset 6px 0 0 var(--oy-mint), var(--oy-shadow-soft);
    text-shadow: none;
}

#send_form::before,
#send_form::after {
    content: "";
    position: absolute;
    width: 22px;
    height: 22px;
    pointer-events: none;
}

#send_form::before {
    top: 5px;
    left: 5px;
    border-top: 1px solid var(--oy-crimson);
    border-left: 1px solid var(--oy-crimson);
}

#send_form::after {
    right: 5px;
    bottom: 5px;
    border-right: 1px solid var(--oy-teal);
    border-bottom: 1px solid var(--oy-teal);
}

#send_form:focus-within {
    border-color: var(--oy-crimson);
    box-shadow: inset 6px 0 0 var(--oy-crimson), 0 0 0 2px rgba(188, 83, 93, 0.12), var(--oy-shadow-soft);
}

#send_textarea {
    margin: 0;
    padding: 11px 14px;
    color: var(--oy-ink);
    border: 1px solid var(--oy-line-soft);
    border-radius: var(--oy-radius-xs);
    background-color: rgba(255, 255, 255, 0.76);
    box-shadow: none;
    font-family: var(--oy-font-serif);
    line-height: 1.65;
    text-shadow: none;
}

#send_textarea::placeholder {
    color: var(--oy-muted);
    opacity: 0.82;
}

#leftSendForm > div,
#rightSendForm > div {
    color: var(--oy-teal);
    border-radius: var(--oy-radius-xs);
    background-color: transparent;
    text-shadow: none;
}

#leftSendForm > div:hover,
#rightSendForm > div:hover {
    color: var(--oy-crimson);
    background-color: rgba(247, 232, 232, 0.76);
    filter: none;
}

#options_button,
#extensionsMenuButton {
    color: var(--oy-crimson);
    border: 1px solid var(--oy-line-soft);
    background-color: rgba(204, 226, 218, 0.54);
}

#send_but.fa-paper-plane {
    color: var(--oy-crimson);
    border-color: transparent;
    background-color: transparent;
    text-shadow: none;
}

#send_but.fa-paper-plane:hover {
    color: var(--oy-white);
    background-color: var(--oy-coral);
}

#send_but.fa-paper-plane::before {
    color: currentColor;
    opacity: 1;
}

#send_form .mes_stop,
#send_but.mes_stop {
    color: var(--oy-white);
    background-color: var(--oy-crimson);
}

#options,
#extensionsMenu {
    color: var(--oy-ink);
    border: 1px solid var(--oy-line);
    border-radius: var(--oy-radius-sm);
    background-color: rgba(255, 255, 255, 0.98);
    background-image: var(--oy-paper-texture);
    background-size: 420px 420px;
    box-shadow: var(--oy-shadow);
    text-shadow: none;
}

/* 通用抽屉视觉与表单令牌；结构尺寸仍由各窗口官方规则负责。 */

.drawer-content {
    color: var(--oy-ink);
    border-color: var(--oy-line);
    background-color: rgba(255, 255, 255, 0.97);
    background-image:
        linear-gradient(90deg, var(--oy-crimson) 0 34%, var(--oy-coral) 34% 53%, var(--oy-mint) 53% 78%, var(--oy-teal) 78% 100%),
        var(--oy-paper-texture);
    background-position: top, center;
    background-repeat: no-repeat, repeat;
    background-size: 100% 5px, 420px 420px;
    box-shadow: var(--oy-shadow);
    text-shadow: none;
}

:is(
    #left-nav-panel,
    #rm_api_block,
    #AdvancedFormatting,
    #WorldInfo,
    #user-settings-block,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement,
    #right-nav-panel,
    .popup,
    #options,
    #extensionsMenu
) :is(input:not([type="range"]):not([type="checkbox"]):not([type="radio"]), textarea, select, .select2-selection) {
    color: var(--oy-ink);
    border-color: var(--oy-line-soft);
    border-radius: var(--oy-radius-xs);
    background-color: rgba(255, 255, 255, 0.92);
    font-family: var(--oy-font-ui);
    box-shadow: inset 3px 0 0 rgba(204, 226, 218, 0.68);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

:is(
    #left-nav-panel,
    #rm_api_block,
    #AdvancedFormatting,
    #WorldInfo,
    #user-settings-block,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement,
    #right-nav-panel,
    .popup
) :is(select option, select optgroup, select option:not(:checked)) {
    color: var(--oy-ink) !important;
    background-color: var(--oy-white) !important;
}

:is(
    #left-nav-panel,
    #rm_api_block,
    #AdvancedFormatting,
    #WorldInfo,
    #user-settings-block,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement,
    #right-nav-panel,
    .popup
) select option:checked {
    color: var(--oy-crimson) !important;
    background-color: var(--oy-mint) !important;
}

:is(
    #left-nav-panel,
    #rm_api_block,
    #AdvancedFormatting,
    #WorldInfo,
    #user-settings-block,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement,
    #right-nav-panel,
    .popup,
    #options,
    #extensionsMenu
) :is(input[type="range"], input[type="checkbox"], input[type="radio"]) {
    accent-color: var(--oy-crimson);
}

:is(
    #left-nav-panel,
    #rm_api_block,
    #AdvancedFormatting,
    #WorldInfo,
    #user-settings-block,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement,
    #right-nav-panel,
    .popup,
    #options,
    #extensionsMenu
) :is(.menu_button, button) {
    color: var(--oy-crimson);
    border-color: var(--oy-line-soft);
    border-radius: var(--oy-radius-xs);
    background-color: rgba(247, 232, 232, 0.74);
    box-shadow: none;
    text-shadow: none;
}

:is(
    #left-nav-panel,
    #rm_api_block,
    #AdvancedFormatting,
    #WorldInfo,
    #user-settings-block,
    #Backgrounds,
    #rm_extensions_block,
    #PersonaManagement,
    #right-nav-panel,
    .popup,
    #options,
    #extensionsMenu
) :is(.menu_button, button):hover {
    color: var(--oy-white);
