        order: 0;
        min-width: 0;
        margin-right: 0;
        padding: 0 10px 10px;
        border-right: 0;
        border-left: 1px solid var(--oy-line-soft);
    }

    #chat .mes[is_user="false"] {
        display: grid;
        grid-template-columns: var(--oy-avatar-size) minmax(0, 1fr);
        grid-template-rows: auto auto auto auto auto auto;
        column-gap: 10px;
        align-items: start;
    }

    #chat .mes[is_user="false"] > .mesAvatarWrapper {
        grid-column: 1;
        grid-row: 1 / span 2;
        order: 0;
        width: var(--oy-avatar-size);
        margin: 0;
    }

    #chat .mes[is_user="false"] > .mes_block {
        display: contents;
    }

    #chat .mes[is_user="false"] > .mes_block > .ch_name {
        grid-column: 2;
        grid-row: 1;
        min-width: 0;
    }

    #chat .mes[is_user="false"] > .mes_block > .mes_reasoning_details {
        grid-column: 2;
        grid-row: 2;
        min-width: 0;
    }

    #chat .mes[is_user="false"] > .mes_block > .mes_text {
        grid-column: 1 / -1;
        grid-row: 3;
        min-width: 0;
    }

    #chat .mes[is_user="false"] > .mes_block > .mes_media_wrapper {
        grid-column: 1 / -1;
        grid-row: 4;
        min-width: 0;
    }

    #chat .mes[is_user="false"] > .mes_block > .mes_file_wrapper {
        grid-column: 1 / -1;
        grid-row: 5;
        min-width: 0;
    }

    #chat .mes[is_user="false"] > .mes_block > .mes_bias {
        grid-column: 1 / -1;
        grid-row: 6;
        min-width: 0;
    }

    #chat .mes[is_user="false"]::before,
    #chat .mes[is_user="true"]::before {
        top: 7px;
        right: 13px;
        left: auto;
        writing-mode: horizontal-tb;
        font-size: 8px;
        letter-spacing: 0.12em;
    }

    #chat .mes:not([is_system="true"])::after {
        right: 10px;
        bottom: 7px;
        left: auto;
        font-size: 22px;
    }

    #chat :is(.mes_text, .mes_reasoning) {
        font-size: 15px;
        line-height: 1.8;
    }

    #chat .mes[is_user="true"] :is(.mes_text, .mes_reasoning),
    #chat .mes[is_user="false"] :is(.mes_text, .mes_reasoning) {
        padding: 8px 10px;
    }

    #send_form {
        border-radius: var(--oy-radius-sm);
        box-shadow: inset 4px 0 0 var(--oy-mint), var(--oy-shadow-soft);
    }

    #send_textarea {
        padding: 9px 10px;
    }

    .drawer-content {
        border-radius: 0 0 var(--oy-radius-md) var(--oy-radius-md);
    }

    #left-nav-panel .drawer-content,
    #right-nav-panel .drawer-content {
        border: 1px solid var(--oy-line);
        border-top: 5px solid var(--oy-crimson);
    }

    #openai_api-presets {
        padding: 6px;
        color: var(--oy-ink);
        border: 1px solid var(--oy-line-soft);
        border-radius: var(--oy-radius-xs);
        background-color: var(--oy-white);
    }

    #settings_preset_openai {
        color: var(--oy-ink);
        border: 1px solid var(--oy-line);
        background-color: var(--oy-white);
        opacity: 1;
        filter: none;
        text-shadow: none;
    }
}

@media (prefers-reduced-motion: reduce) {
    :is(#chat, #top-bar, #send_form, .drawer-content, .popup, .options-content, .menu) {
        scroll-behavior: auto;
        transition-duration: 0.01ms;
        animation-duration: 0.01ms;
        animation-iteration-count: 1;
    }
}

/* 远程背景/纹理/字体加载失败时仍保持纯色、系统字体与原生图标。 */

body,
#bg1,
#bg_custom {
    background-color: var(--oy-white);
}

#chat .mes:not([is_system="true"]),
.drawer-content,
:is(.popup, .popup-content, .popup-body, .popper-modal),
#send_form {
    background-color: rgba(255, 255, 255, 0.96);
}

#chat .mes[is_user="true"] {
    background-color: rgba(247, 232, 232, 0.97);
}

#chat .mes:not([is_system="true"]) .avatar {
    outline: 1px solid var(--oy-line-soft);
    outline-offset: 1px;
}

#send_but,
#options_button,
#extensionsMenuButton {
    outline: 1px solid rgba(188, 83, 93, 0.18);
    outline-offset: 1px;
}
